package pe.vichaval.gestionriego.parcela.dto;import jakarta.validation.constraints.*;import java.math.BigDecimal;public class ParcelaForm{@NotBlank private String codigo;@NotBlank private String nombre;@NotNull@DecimalMin("0.01")private BigDecimal hectareas;private String cultivo;@NotNull private Long agricultorId;public String getCodigo(){return codigo;}public void setCodigo(String x){codigo=x;}public String getNombre(){return nombre;}public void setNombre(String x){nombre=x;}public BigDecimal getHectareas(){return hectareas;}public void setHectareas(BigDecimal x){hectareas=x;}public String getCultivo(){return cultivo;}public void setCultivo(String x){cultivo=x;}public Long getAgricultorId(){return agricultorId;}public void setAgricultorId(Long x){agricultorId=x;}}